dashboard.definition:
{
  "title": "gNMI Operation",
  "description": "Is gnmic connected, which subscriptions stream, and why a target fails.",
  "inputs": {
    "input_tr": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "tr",
        "defaultValue": "-15m,now"
      }
    },
    "input_cause": {
      "type": "input.dropdown",
      "title": "Failure cause",
      "dataSources": {
        "primary": "ds_causes"
      },
      "options": {
        "token": "cause",
        "defaultValue": "*",
        "items": ">frame(label, value) | objects()"
      },
      "context": {
        "formattedConfig": {
          "number": {
            "prefix": ""
          }
        },
        "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
        "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$tr.earliest$",
            "latest": "$tr.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_intro": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "The page starts at the last 15 minutes so a corrected configuration is not hidden by old errors. Click a **subscription** or a **target** to open its data on **gNMI Data**. Click a failure cause to filter the error table. The **Troubleshooting guide** tab explains each error.",
        "fontSize": "default"
      }
    },
    "viz_kpi_connected": {
      "type": "splunk.singlevalue",
      "title": "Targets connected",
      "dataSources": {
        "primary": "ds_kpi_connected"
      },
      "options": {
        "majorFontSize": 44,
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "underLabel": "last 5 minutes"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "gnmi_trial",
            "dashboard": "gnmi_data",
            "newTab": false,
            "tokens": [
              {
                "token": "tr.earliest",
                "value": "$tr.earliest$"
              },
              {
                "token": "tr.latest",
                "value": "$tr.latest$"
              }
            ]
          }
        }
      ]
    },
    "viz_kpi_failing": {
      "type": "splunk.singlevalue",
      "title": "Targets in failure",
      "dataSources": {
        "primary": "ds_kpi_failing"
      },
      "options": {
        "majorFontSize": 44,
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "underLabel": "channel not READY",
        "backgroundColor": "> majorValue | rangeValue(backgroundColorEditorConfig)"
      },
      "context": {
        "backgroundColorEditorConfig": [
          {
            "to": 1,
            "value": "#118832"
          },
          {
            "from": 1,
            "value": "#d41f1f"
          }
        ]
      }
    },
    "viz_kpi_errors": {
      "type": "splunk.singlevalue",
      "title": "gnmic errors",
      "dataSources": {
        "primary": "ds_kpi_errors"
      },
      "options": {
        "majorFontSize": 44,
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "backgroundColor": "> majorValue | rangeValue(backgroundColorEditorConfig)"
      },
      "context": {
        "backgroundColorEditorConfig": [
          {
            "to": 1,
            "value": "#118832"
          },
          {
            "from": 1,
            "value": "#cba700"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "type": "custom",
            "query": "`gnmi_ops_index` `gnmi_runtime_sourcetype` level=ERROR | table _time target subscription grpc_code failure_cause err",
            "earliest": "$tr.earliest$",
            "latest": "$tr.latest$",
            "newTab": true
          }
        }
      ]
    },
    "viz_kpi_updates": {
      "type": "splunk.singlevalue",
      "title": "gNMI updates received",
      "dataSources": {
        "primary": "ds_kpi_updates"
      },
      "options": {
        "majorFontSize": 44,
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "gnmi_trial",
            "dashboard": "gnmi_data",
            "newTab": false,
            "tokens": [
              {
                "token": "tr.earliest",
                "value": "$tr.earliest$"
              },
              {
                "token": "tr.latest",
                "value": "$tr.latest$"
              }
            ]
          }
        }
      ]
    },
    "viz_kpi_hec": {
      "type": "splunk.singlevalue",
      "title": "Collector send failures to HEC",
      "dataSources": {
        "primary": "ds_kpi_hec"
      },
      "options": {
        "majorFontSize": 44,
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "backgroundColor": "> majorValue | rangeValue(backgroundColorEditorConfig)"
      },
      "context": {
        "backgroundColorEditorConfig": [
          {
            "to": 1,
            "value": "#118832"
          },
          {
            "from": 1,
            "value": "#d41f1f"
          }
        ]
      }
    },
    "viz_target_status": {
      "type": "splunk.table",
      "title": "Target status (click a target to open its data)",
      "dataSources": {
        "primary": "ds_target_status"
      },
      "options": {
        "count": 10,
        "headerVisibility": "fixed",
        "showInternalFields": false,
        "columnFormat": {
          "status": {
            "rowBackgroundColors": "> table | seriesByName(\"status\") | matchValue(statusColors)"
          }
        }
      },
      "context": {
        "statusColors": [
          {
            "match": "connected",
            "value": "#118832"
          },
          {
            "match": "not connected",
            "value": "#d41f1f"
          },
          {
            "value": "#5c6773"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "gnmi_trial",
            "dashboard": "gnmi_data",
            "newTab": false,
            "tokens": [
              {
                "token": "target",
                "value": "$row.target.value$"
              },
              {
                "token": "tr.earliest",
                "value": "$tr.earliest$"
              },
              {
                "token": "tr.latest",
                "value": "$tr.latest$"
              }
            ]
          }
        }
      ]
    },
    "viz_channel": {
      "type": "splunk.line",
      "title": "gRPC channel state per target (3 = READY, 4 = TRANSIENT_FAILURE)",
      "dataSources": {
        "primary": "ds_channel"
      },
      "options": {
        "yAxisMin": 0,
        "yAxisMax": 5,
        "legendDisplay": "bottom",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleText": "state"
      }
    },
    "viz_causes_time": {
      "type": "splunk.column",
      "title": "Failures by cause (click a cause to filter the errors below)",
      "dataSources": {
        "primary": "ds_causes_time"
      },
      "options": {
        "stackMode": "stacked",
        "legendDisplay": "bottom",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleText": "errors"
      },
      "eventHandlers": [
        {
          "type": "drilldown.setToken",
          "options": {
            "tokens": [
              {
                "token": "cause",
                "key": "name"
              }
            ]
          }
        }
      ]
    },
    "viz_subscriptions": {
      "type": "splunk.table",
      "title": "Subscriptions per target (click to open the data)",
      "dataSources": {
        "primary": "ds_subscriptions"
      },
      "options": {
        "count": 12,
        "headerVisibility": "fixed",
        "showInternalFields": false,
        "columnFormat": {
          "health": {
            "rowBackgroundColors": "> table | seriesByName(\"health\") | matchValue(healthColors)"
          }
        }
      },
      "context": {
        "healthColors": [
          {
            "match": "streaming",
            "value": "#118832"
          },
          {
            "match": "not started: see errors",
            "value": "#d41f1f"
          },
          {
            "match": "waiting",
            "value": "#cba700"
          },
          {
            "value": "#5c6773"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "gnmi_trial",
            "dashboard": "gnmi_data",
            "newTab": false,
            "tokens": [
              {
                "token": "target",
                "value": "$row.target.value$"
              },
              {
                "token": "subscription",
                "value": "$row.subscription.value$"
              },
              {
                "token": "tr.earliest",
                "value": "$tr.earliest$"
              },
              {
                "token": "tr.latest",
                "value": "$tr.latest$"
              }
            ]
          }
        }
      ]
    },
    "viz_exports": {
      "type": "splunk.table",
      "title": "Collector exports to Splunk HEC",
      "dataSources": {
        "primary": "ds_exports"
      },
      "options": {
        "count": 12,
        "headerVisibility": "fixed",
        "showInternalFields": false
      }
    },
    "viz_errors": {
      "type": "splunk.table",
      "title": "gnmic errors and warnings (cause: $cause$, click to open in Search)",
      "dataSources": {
        "primary": "ds_errors"
      },
      "options": {
        "count": 12,
        "headerVisibility": "fixed",
        "showInternalFields": false
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "type": "custom",
            "query": "`gnmi_ops_index` `gnmi_runtime_sourcetype` (level=ERROR OR level=WARN) target=\"$row.target.value$\"",
            "earliest": "$tr.earliest$",
            "latest": "$tr.latest$",
            "newTab": true
          }
        }
      ]
    },
    "viz_log": {
      "type": "splunk.table",
      "title": "gnmic log (without the collector's /metrics scrapes)",
      "dataSources": {
        "primary": "ds_log"
      },
      "options": {
        "count": 15,
        "headerVisibility": "fixed",
        "showInternalFields": false
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "type": "custom",
            "query": "`gnmi_ops_index` `gnmi_runtime_sourcetype`",
            "earliest": "$tr.earliest$",
            "latest": "$tr.latest$",
            "newTab": true
          }
        }
      ]
    },
    "viz_guide": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### How gnmic works\n\nFor every target, gnmic opens one gRPC channel (TLS unless `insecure` is true), sends the username and password as gRPC metadata, and starts one gNMI Subscribe RPC per subscription. The device then streams updates. When a channel or an RPC fails, gnmic logs the error and tries again after the retry timer (30s in this lab). It keeps running while the device is down.\n\n### Three signals in Splunk\n\n- **Runtime log** (macro `gnmi_ops_index`, sourcetype `gnmi:runtime`). gnmic writes JSON lines with `level`, `msg`, `target`, `subscription`, and `err`. A connection problem appears as `level=ERROR msg=\"subscription receive error\"`. The `err` text holds the gRPC status code, for example `code = Unavailable ... dial tcp 10.0.0.1:9339: i/o timeout`. This app adds `grpc_code` and a plain `failure_cause`.\n- **Target metrics** (macro `gnmi_metrics_index`). `gnmic_target_up` is 1 when the gNMI connection is established. `gnmic_target_connection_state` is the gRPC channel state: 0 UNKNOWN, 1 IDLE, 2 CONNECTING, 3 READY, 4 TRANSIENT_FAILURE, 5 SHUTDOWN.\n- **Subscribe counters**. `gnmic_subscribe_number_of_failed_subscribe_request_messages_total` counts Subscribe RPCs that could not start. `gnmic_subscribe_number_of_received_subscribe_response_messages_total` counts updates received. That counter only exists once data flows, so a missing counter also means no data.\n\nThe collector scrapes those metrics from gnmic's local API at `127.0.0.1:7890/metrics`. It also scrapes its own counters from `127.0.0.1:8888`, so failed sends to HEC are visible too.\n\n### Reading the error\n\n- `i/o timeout`, `context deadline exceeded`: no answer on the gNMI port. Check the IP address, routing, ACL, or firewall between the collector and the device.\n- `connection refused`: the device answers, but nothing listens on that port. gNMI is not enabled, or the port is wrong (see Devices).\n- `first record does not look like a TLS handshake`, `x509`, `certificate`: TLS settings differ between gnmic and the device. Check insecure and skip-verify on the gNMI page, and the device certificate.\n- `Unauthenticated`, `PermissionDenied`: login rejected or the user lacks gNMI rights. Check username, password, and AAA authorization on the device.\n- `Unimplemented`, `NotFound`, `InvalidArgument`: the device refuses this path, mode, or encoding. Only that subscription fails. Remove the path or use one the device supports. Nokia SR Linux accepts only its native YANG paths, which is why the template has `srl-` subscriptions.\n\n### Debug from the collector host\n\n1. Port reachable: `timeout 3 bash -c 'echo >/dev/tcp/DEVICE/PORT' && echo open`\n2. gNMI, TLS, and login in one call: `gnmic -a DEVICE:PORT -u USER --skip-verify capabilities`. Use `--insecure` for a device without TLS. gnmic asks for the password when `-p` is left out.\n3. One read: `gnmic -a DEVICE:PORT -u USER --skip-verify get --path /system/state`\n4. Add `--debug` to print each RPC and the gRPC channel state changes.\n5. Running state of this gnmic: `curl -s http://127.0.0.1:7890/api/v1/targets`. Passwords appear as `****`.\n6. Raw counters: `curl -s http://127.0.0.1:7890/metrics | grep gnmic_`\n\nDocs: [global flags](https://gnmic.openconfig.net/global_flags/), [capabilities](https://gnmic.openconfig.net/cmd/capabilities/), [get](https://gnmic.openconfig.net/cmd/get/), [targets](https://gnmic.openconfig.net/user_guide/targets/targets/), [subscriptions](https://gnmic.openconfig.net/user_guide/subscriptions/), [API server and metrics](https://gnmic.openconfig.net/user_guide/api/api_intro/).",
        "fontSize": "default"
      }
    }
  },
  "dataSources": {
    "ds_causes": {
      "type": "ds.search",
      "options": {
        "query": "`gnmi_ops_index` `gnmi_runtime_sourcetype` level=ERROR failure_cause=*\n| stats count BY failure_cause\n| eval label=failure_cause.\" (\".count.\")\", value=failure_cause\n| append [| makeresults | eval label=\"All\", value=\"*\", count=-1]\n| sort count\n| table label value",
        "refresh": "1m",
        "refreshType": "delay"
      }
    },
    "ds_kpi_connected": {
      "type": "ds.search",
      "options": {
        "query": "| mstats latest(_value) AS up WHERE `gnmi_metrics_index` metric_name=\"gnmic_target_up\" BY name\n| stats sum(up) AS connected count AS total\n| eval value=coalesce(connected, 0).\" of \".coalesce(total, 0)\n| fields value",
        "refresh": "15s",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_kpi_failing": {
      "type": "ds.search",
      "options": {
        "query": "| mstats latest(_value) AS state WHERE `gnmi_metrics_index` metric_name=\"gnmic_target_connection_state\" BY name\n| where state!=3\n| stats count",
        "refresh": "15s",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_kpi_errors": {
      "type": "ds.search",
      "options": {
        "query": "`gnmi_ops_index` `gnmi_runtime_sourcetype` level=ERROR | stats count",
        "refresh": "15s",
        "refreshType": "delay"
      }
    },
    "ds_kpi_updates": {
      "type": "ds.search",
      "options": {
        "query": "| mstats max(_value) AS hi min(_value) AS lo WHERE `gnmi_metrics_index` metric_name=\"gnmic_subscribe_number_of_received_subscribe_response_messages*\" BY extracted_source subscription\n| eval received=hi-lo\n| append [| makeresults | eval received=0]\n| stats sum(received) AS received\n| eval received=round(received, 0)",
        "refresh": "15s",
        "refreshType": "delay"
      }
    },
    "ds_kpi_hec": {
      "type": "ds.search",
      "options": {
        "query": "| mstats max(_value) AS hi min(_value) AS lo WHERE `gnmi_metrics_index` metric_name=\"otelcol_exporter_send_failed*\" BY metric_name exporter\n| eval failed=hi-lo\n| append [| makeresults | eval failed=0]\n| stats sum(failed) AS failed\n| eval failed=round(failed, 0)",
        "refresh": "15s",
        "refreshType": "delay"
      }
    },
    "ds_target_status": {
      "type": "ds.search",
      "options": {
        "query": "| mstats latest(_value) AS value WHERE `gnmi_metrics_index` (metric_name=\"gnmic_target_up\" OR metric_name=\"gnmic_target_connection_state\") BY name metric_name\n| eval metric=if(metric_name=\"gnmic_target_up\", \"up\", \"state\")\n| xyseries name metric value\n| join type=left name\n    [ search `gnmi_ops_index` `gnmi_runtime_sourcetype` level=ERROR grpc_code=* earliest=-24h\n    | stats latest(_time) AS last_error latest(failure_cause) AS last_cause latest(grpc_code) AS grpc_code BY target\n    | rename target AS name ]\n| eval status=if(up=1, \"connected\", \"not connected\"),\n       channel=case(state=0, \"UNKNOWN\", state=1, \"IDLE\", state=2, \"CONNECTING\", state=3, \"READY\", state=4, \"TRANSIENT_FAILURE (gnmic retries)\", state=5, \"SHUTDOWN\"),\n       last_error=strftime(last_error, \"%Y-%m-%d %H:%M:%S\")\n| rename name AS target\n| table target status channel last_error grpc_code last_cause",
        "refresh": "15s",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_channel": {
      "type": "ds.search",
      "options": {
        "query": "| mstats max(_value) AS state WHERE `gnmi_metrics_index` metric_name=\"gnmic_target_connection_state\" span=1m BY name\n| xyseries _time name state",
        "refresh": "30s",
        "refreshType": "delay"
      }
    },
    "ds_causes_time": {
      "type": "ds.search",
      "options": {
        "query": "`gnmi_ops_index` `gnmi_runtime_sourcetype` level=ERROR failure_cause=*\n| timechart span=1m count BY failure_cause",
        "refresh": "30s",
        "refreshType": "delay"
      }
    },
    "ds_subscriptions": {
      "type": "ds.search",
      "options": {
        "query": "| mstats latest(_value) AS value WHERE `gnmi_metrics_index` metric_name=\"gnmic_subscribe_number_of_*\" BY metric_name extracted_source subscription\n| eval counter=case(like(metric_name, \"%failed_subscribe_request%\"), \"failed_starts\", like(metric_name, \"%received_subscribe_response%\"), \"updates_received\", true(), metric_name),\n       key=extracted_source.\"|\".subscription\n| xyseries key counter value\n| eval target=mvindex(split(key, \"|\"), 0), subscription=mvindex(split(key, \"|\"), 1),\n       updates_received=round(coalesce(updates_received, 0), 0), failed_starts=round(coalesce(failed_starts, 0), 0),\n       health=case(updates_received>0, \"streaming\", failed_starts>0, \"not started: see errors\", true(), \"waiting\")\n| table target subscription health updates_received failed_starts\n| sort target subscription",
        "refresh": "30s",
        "refreshType": "delay"
      }
    },
    "ds_exports": {
      "type": "ds.search",
      "options": {
        "query": "| mstats max(_value) AS hi min(_value) AS lo WHERE `gnmi_metrics_index` metric_name=\"otelcol_exporter_*\" BY metric_name exporter\n| eval count=hi-lo,\n       kind=case(like(metric_name, \"%send_failed%\"), \"failed\", like(metric_name, \"%sent%\"), \"sent\", true(), null())\n| where isnotnull(kind)\n| eval signal=case(like(metric_name, \"%metric_points%\"), \"metric points\", like(metric_name, \"%log_records%\"), \"log records\", true(), \"other\"),\n       row=exporter.\" (\".signal.\")\"\n| xyseries row kind count\n| eval sent=round(coalesce(sent, 0), 0), failed=round(coalesce(failed, 0), 0)\n| rename row AS exporter\n| table exporter sent failed",
        "refresh": "30s",
        "refreshType": "delay"
      }
    },
    "ds_errors": {
      "type": "ds.search",
      "options": {
        "query": "`gnmi_ops_index` `gnmi_runtime_sourcetype` (level=ERROR OR level=WARN)\n| where \"$cause$\"=\"*\" OR failure_cause==\"$cause$\"\n| table _time level target subscription grpc_code failure_cause err\n| head 200",
        "refresh": "15s",
        "refreshType": "delay"
      }
    },
    "ds_log": {
      "type": "ds.search",
      "options": {
        "query": "`gnmi_ops_index` `gnmi_runtime_sourcetype` NOT \"GET /metrics\"\n| eval message=coalesce(msg, _raw)\n| table _time level message target subscription\n| head 300",
        "refresh": "15s",
        "refreshType": "delay"
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_tr",
      "input_cause"
    ],
    "tabs": {
      "items": [
        {
          "layoutId": "layout_status",
          "label": "Status"
        },
        {
          "layoutId": "layout_guide",
          "label": "Troubleshooting guide"
        }
      ]
    },
    "layoutDefinitions": {
      "layout_status": {
        "type": "grid",
        "options": {
          "width": 1440,
          "height": 2040
        },
        "structure": [
          {
            "item": "viz_intro",
            "type": "block",
            "position": {
              "x": 0,
              "y": 0,
              "w": 1440,
              "h": 70
            }
          },
          {
            "item": "viz_kpi_connected",
            "type": "block",
            "position": {
              "x": 0,
              "y": 70,
              "w": 288,
              "h": 130
            }
          },
          {
            "item": "viz_kpi_failing",
            "type": "block",
            "position": {
              "x": 288,
              "y": 70,
              "w": 288,
              "h": 130
            }
          },
          {
            "item": "viz_kpi_errors",
            "type": "block",
            "position": {
              "x": 576,
              "y": 70,
              "w": 288,
              "h": 130
            }
          },
          {
            "item": "viz_kpi_updates",
            "type": "block",
            "position": {
              "x": 864,
              "y": 70,
              "w": 288,
              "h": 130
            }
          },
          {
            "item": "viz_kpi_hec",
            "type": "block",
            "position": {
              "x": 1152,
              "y": 70,
              "w": 288,
              "h": 130
            }
          },
          {
            "item": "viz_target_status",
            "type": "block",
            "position": {
              "x": 0,
              "y": 200,
              "w": 1440,
              "h": 220
            }
          },
          {
            "item": "viz_channel",
            "type": "block",
            "position": {
              "x": 0,
              "y": 420,
              "w": 720,
              "h": 300
            }
          },
          {
            "item": "viz_causes_time",
            "type": "block",
            "position": {
              "x": 720,
              "y": 420,
              "w": 720,
              "h": 300
            }
          },
          {
            "item": "viz_subscriptions",
            "type": "block",
            "position": {
              "x": 0,
              "y": 720,
              "w": 840,
              "h": 420
            }
